<?php
declare(strict_types=1);
namespace Morshed\Product;
use Morshed\Core\{Database,Audit,Security,Problem};
use Morshed\Notifications\{TsmsSendOnlyGateway,CurlFormTransport};
/** Account-owned SDK preference is not authentication; the provider still enforces its native permission. */
final class Messaging
{
 public function __construct(private Database $db,private array $config=[],private ?TsmsSendOnlyGateway $sms=null){}
 public function storage():void {
  if($this->db->featureReady('messaging24'))return;
  try{$this->db->run('SELECT user_id FROM m_message_permissions LIMIT 0');$this->db->run('SELECT notification_id FROM m_sms_deliveries LIMIT 0');$this->db->run('SELECT notification_id FROM m_eitaa_deliveries LIMIT 0');$this->db->run('SELECT notification_id FROM m_message_schedule LIMIT 0');$this->db->run('SELECT last_run FROM m_message_worker LIMIT 0');}
  catch(\PDOException $e){if((int)($e->errorInfo[1]??0)!==1146)throw $e;if($this->db->pdo->inTransaction())throw new \LogicException('Prepare message storage before transaction');$schema=@file_get_contents(__DIR__.'/../../database/eitaa-outbox.sql');if($schema===false)throw new \RuntimeException('Message schema unavailable');foreach(explode(';',$schema) as $statement){if(trim($statement)!=='')$this->db->run($statement);}}
  $this->db->markFeatureReady('messaging24');$this->db->markFeatureReady('eitaa-delivery');
 }
 public function permission(array $a,bool $allowed,string $subject):void {
  $uid=(new Policy($this->db))->user($a);$this->storage();$identity=$this->db->one("SELECT subject FROM m_auth_identities WHERE user_id=? AND provider='eitaa'",[$uid]);if(!$identity||!preg_match('/^[1-9][0-9]{0,19}$/D',$subject)||!hash_equals($identity['subject'],$subject))throw new Problem('EITAA_NOT_LINKED','مجوز فقط برای حساب ایتای متصل به همین حساب ثبت می‌شود.',409);
  $this->db->tx(function()use($uid,$allowed){$this->db->one('SELECT id FROM m_users WHERE id=? FOR UPDATE',[$uid]);$this->db->run("INSERT INTO m_message_permissions VALUES(?,?,'client_sdk',?) ON DUPLICATE KEY UPDATE eitaa_allowed=VALUES(eitaa_allowed),source='client_sdk',updated_at=VALUES(updated_at)",[$uid,(int)$allowed,time()]);if($allowed)$this->db->run("UPDATE m_eitaa_deliveries d JOIN m_notifications n ON n.id=d.notification_id SET d.state='pending',d.updated_at=? WHERE n.user_id=? AND d.state='permission_required' AND n.created_at>?",[time(),$uid,time()-3600]);$this->db->run('UPDATE m_notifications SET read_at=COALESCE(read_at,?) WHERE id=? AND user_id=?',[time(),$this->permissionId($uid),$uid]);(new Audit($this->db))->add($uid,'site',$allowed?'eitaa.permission_allowed':'eitaa.permission_declined',$uid);});
 }
 private function permissionId(string $uid):string {return substr(hash('sha256','eitaa-permission24:'.$uid),0,32);}
 public function needsPermission(array $a):bool {
  $uid=(new Policy($this->db))->user($a);$this->storage();$identity=$this->db->one("SELECT subject FROM m_auth_identities WHERE user_id=? AND provider='eitaa'",[$uid]);if(!$identity)return false;$permission=$this->db->one('SELECT eitaa_allowed FROM m_message_permissions WHERE user_id=?',[$uid]);
  if(!$permission)$this->db->run("INSERT IGNORE INTO m_notifications(id,user_id,title,body,created_at,destination,category) VALUES(?,?,?,?,?,'/notifications','system')",[$this->permissionId($uid),$uid,'دریافت پیام‌های مرشد در ایتا','برای دریافت نتیجهٔ درخواست مشاوره و پیام‌های مرتبط، از همین صفحه داخل برنامک ایتا اجازهٔ دریافت پیام را انتخاب کنید.',time()]);
  return !$permission||!(bool)$permission['eitaa_allowed'];
 }
 public function enabled(string $channel):bool {if($channel==='eitaa'){$e=$this->config['eitaa']??[];return ($e['enabled']??false)&&($e['live_verified']??false)&&strlen($e['app_token']??'')>=16;}$s=$this->config['sms']??[];return ($s['enabled']??false)&&($s['https_transport_confirmed']??$s['https_post_confirmed']??false);}
 public function recipients(array $a,string $channel,string $query='',int $page=1):array {
  (new Policy($this->db))->admin($a,true);$this->storage();Policy::choice($channel,['eitaa','sms']);$q=Policy::text($query,160,0);$args=[];$where="u.status='active'".($channel==='eitaa'?" AND i.subject REGEXP '^[1-9][0-9]{0,19}$'":" AND u.phone IS NOT NULL AND u.phone_verified_at IS NOT NULL");if($q!==''){$pattern=Policy::query($q);$where.=' AND (u.display_name LIKE ? OR CONVERT(n.subject USING utf8mb4) LIKE ? OR CONVERT(u.phone USING utf8mb4) LIKE ?)';$args=[$pattern,$pattern,$pattern];}$page=Policy::integer($page,1,10000);
  $rows=$this->db->all("SELECT u.id,u.display_name,u.phone,n.subject AS username,i.subject AS eitaa_subject,p.eitaa_allowed FROM m_users u LEFT JOIN m_auth_identities n ON n.user_id=u.id AND n.provider='local_username' LEFT JOIN m_auth_identities i ON i.user_id=u.id AND i.provider='eitaa' LEFT JOIN m_message_permissions p ON p.user_id=u.id WHERE ".$where.' ORDER BY u.display_name,u.id LIMIT 51 OFFSET '.(($page-1)*50),$args);$more=count($rows)>50;$rows=array_slice($rows,0,50);foreach($rows as &$row){$row['phone_hint']=$row['phone']?substr($row['phone'],0,4).'•••'.substr($row['phone'],-4):'';unset($row['phone'],$row['eitaa_subject']);}unset($row);return ['contacts'=>$rows,'recipientPage'=>$page,'hasMore'=>$more];
 }
 public function send(array $a,array $d):array {
  (new Policy($this->db))->admin($a,true);$this->storage();$channel=Policy::choice($d['channel']??'eitaa',['eitaa','sms']);if(!$this->enabled($channel))throw new Problem('PROVIDER_DISABLED','ارسال این کانال در تنظیمات اتصال فعال نیست.',503);
  $ids=$d['user_ids']??[];if(!is_array($ids)||!array_is_list($ids)||!$ids||count($ids)>20)throw new Problem('INVALID_RECIPIENT','بین یک تا بیست مخاطب انتخاب کنید.');foreach($ids as $id){if(!is_string($id)||!Security::validId($id))throw new Problem('INVALID_RECIPIENT','مخاطب معتبر نیست.');}$ids=array_values(array_unique($ids));$key=Policy::text($d['request_id']??'',32);if(!Security::validId($key))throw new Problem('INVALID_INPUT','صفحه را تازه کنید.');$title=Policy::text($d['title']??'',720);if(preg_match_all('/./us',$title)>180)throw new Problem('INVALID_INPUT','عنوان حداکثر ۱۸۰ نویسه است.');$body=Policy::text($d['body']??'',4000);$mode=Policy::choice($d['send_mode']??'immediate',['manual','immediate','scheduled']);$at=$mode==='scheduled'?Consultations::localTimestamp(Policy::text($d['send_at']??'',30)):null;if($mode==='scheduled'&&($at<=time()||$at>time()+31536000))throw new Problem('INVALID_INPUT','زمان ارسال باید در آینده و حداکثر یک سال بعد باشد.');
  return $this->db->tx(function()use($a,$channel,$ids,$key,$title,$body,$mode,$at){$this->db->one('SELECT id FROM m_installation WHERE id=1 FOR UPDATE');$out=[];foreach($ids as $uid){$u=$this->db->one("SELECT u.phone,u.phone_verified_at,i.subject,p.eitaa_allowed FROM m_users u LEFT JOIN m_auth_identities i ON i.user_id=u.id AND i.provider='eitaa' LEFT JOIN m_message_permissions p ON p.user_id=u.id WHERE u.id=? AND u.status='active'",[$uid]);if(!$u||($channel==='eitaa'&&(!(bool)$u['eitaa_allowed']||!preg_match('/^[1-9][0-9]{0,19}$/D',$u['subject']??'')))||($channel==='sms'&&(!$u['phone']||!$u['phone_verified_at'])))throw new Problem('INVALID_RECIPIENT','مخاطب مجاز برای این کانال انتخاب کنید.');$id=substr(hash('sha256','message24:'.$channel.':'.$a['user_id'].':'.$key.':'.$uid),0,32);$old=$this->db->one('SELECT title,body FROM m_notifications WHERE id=?',[$id]);$schedule=$this->db->one('SELECT mode,send_after FROM m_message_schedule WHERE notification_id=?',[$id]);if($old&&$schedule&&($schedule['mode']!==$mode||($mode==='scheduled'&&(int)$schedule['send_after']!==$at)))throw new Problem('CONFLICT','این درخواست قبلاً با زمان‌بندی دیگری ثبت شده است.',409);if($old&&($old['title']!==$title||$old['body']!==$body))throw new Problem('CONFLICT','این درخواست قبلاً با متن دیگری ثبت شده است.',409);$this->db->run("INSERT IGNORE INTO m_notifications(id,user_id,title,body,created_at,destination,category) VALUES(?,?,?,?,?,'/notifications','system')",[$id,$uid,$title,$body,time()]);$table=$channel==='eitaa'?'m_eitaa_deliveries':'m_sms_deliveries';$this->db->run("INSERT IGNORE INTO $table VALUES(?,'pending',?,?)",[$id,time(),time()]);$this->db->run('INSERT IGNORE INTO m_message_schedule VALUES(?,?,?)',[$id,$mode,$at]);$out[$id]=$this->db->one("SELECT state FROM $table WHERE notification_id=?",[$id])['state'];}(new Audit($this->db))->add($a['user_id'],'admin','messages.'.$channel.'_queued',$key);return $out;});
 }
 public function history(array $a,string $channel):array {(new Policy($this->db))->admin($a,true);$this->storage();Policy::choice($channel,['eitaa','sms']);$table=$channel==='eitaa'?'m_eitaa_deliveries':'m_sms_deliveries';return $this->db->all("SELECT d.notification_id,d.state,d.updated_at,u.display_name,n.title,q.mode,q.send_after FROM $table d LEFT JOIN m_message_schedule q ON q.notification_id=d.notification_id JOIN m_notifications n ON n.id=d.notification_id JOIN m_users u ON u.id=n.user_id ORDER BY (d.state IN ('pending','permission_required')) DESC,d.created_at DESC,d.notification_id LIMIT 100");}
 public function dispatchSms(int $limit=3,?string $only=null):array {
  if(!$this->enabled('sms'))return ['disabled'=>true];$this->storage();$rows=$this->db->all("SELECT d.notification_id FROM m_sms_deliveries d LEFT JOIN m_message_schedule q ON q.notification_id=d.notification_id WHERE d.state='pending' AND ".MessageQueue::dueSql()."".($only?' AND d.notification_id=?':'')." ORDER BY d.created_at LIMIT ".max(1,min(10,$limit)),$only?[$only]:[]);$out=[];
  foreach($rows as $row){$id=$row['notification_id'];$payload=$this->db->tx(function()use($id){$r=$this->db->one("SELECT d.state,q.mode AS queue_mode,q.send_after,u.phone,u.phone_verified_at,u.status,n.title,n.body,n.destination,n.created_at AS notification_created_at FROM m_sms_deliveries d LEFT JOIN m_message_schedule q ON q.notification_id=d.notification_id JOIN m_notifications n ON n.id=d.notification_id JOIN m_users u ON u.id=n.user_id WHERE d.notification_id=? FOR UPDATE",[$id]);if(!$r||$r['state']!=='pending'||!MessageQueue::due($r))return null;$state=$r['status']==='active'&&$r['phone']&&$r['phone_verified_at']?(MessageQueue::expiryBase($r)<time()-86400?'expired':'sending'):'not_linked';$this->db->run('UPDATE m_sms_deliveries SET state=?,updated_at=? WHERE notification_id=?',[$state,time(),$id]);return $state==='sending'?$r:null;});if(!$payload)continue;
   $state='submission_uncertain';try{$cfg=$this->config['sms']??[];$cfg['environment']=$cfg['environment']??$this->config['environment']??'staging';$gateway=$this->sms??new TsmsSendOnlyGateway($cfg,new CurlFormTransport());$text=$payload['title']."\n".$payload['body']."\n".rtrim($this->config['origins']['site'],'/').($payload['destination']??'/notifications');$state=$gateway->sendMessage($payload['phone'],$text)->status;}catch(\Throwable $e){}$this->db->run('UPDATE m_sms_deliveries SET state=?,updated_at=? WHERE notification_id=?',[$state,time(),$id]);$out[$id]=$state;
  }return $out;
 }
}
